using System;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "BoneKhopeshOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/BoneKhopeshOmenData")]
public class BoneKhopeshOmenData : OmenData
{
	[Header("Soul Heat 10")]
	[SerializeField]
	private DrawAction soulHeat10BattleAction;

	[SerializeField]
	private OmenLogic soulHeat10OmenLogic;

	[SerializeField]
	private int soulHeat10Value;

	[SerializeField]
	private int soulHeat10Counter;

	[NonSerialized]
	[Header("Soul Heat + Concentration Work Around")]
	private bool concentrationEffectSoulHeat10Trigger;

	[Header("Soul Heat 5")]
	[SerializeField]
	private BattleAction soulHeat5BattleAction;

	[SerializeField]
	private OmenLogic soulHeat5OmenLogic;

	[SerializeField]
	private int soulHeat5Value;

	[SerializeField]
	private int soulHeat5Counter;

	[SerializeField]
	private int soulHeat5SecondActionValue;

	[NonSerialized]
	private bool concentrationEffectSoulHeat5Trigger;

	public int SoulHeat10Counter => soulHeat10Counter;

	public int SoulHeat5Counter => soulHeat5Counter;

	public void ConcentrationEffectSoulHeat10Triggered()
	{
		concentrationEffectSoulHeat10Trigger = true;
	}

	public void ConcentrationEffectSoulHeat5Triggered()
	{
		concentrationEffectSoulHeat5Trigger = true;
	}

	public override void Initialize(OmenInstance omenInstance)
	{
		concentrationEffectSoulHeat10Trigger = false;
		concentrationEffectSoulHeat5Trigger = false;
		ReferenceSingleton<SothisOmensHandler>.Instance.BoneKhopeshOmenAction = delegate(int soulHeatCounter)
		{
			if (soulHeatCounter == soulHeat5Counter)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				if (concentrationEffectSoulHeat5Trigger)
				{
					ReferenceSingleton<PlayerDiceHandHolder>.Instance.ModifyDrawDicesAmountModifier(1);
					concentrationEffectSoulHeat5Trigger = false;
				}
				else
				{
					soulHeat10OmenLogic.ActivateOmen(soulHeat10BattleAction, soulHeat5SecondActionValue, null, null);
				}
				soulHeat5OmenLogic.ActivateOmen(soulHeat5BattleAction, soulHeat5Value, null, null, CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION);
			}
			else if (soulHeatCounter == soulHeat10Counter)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				if (concentrationEffectSoulHeat10Trigger)
				{
					ReferenceSingleton<PlayerDiceHandHolder>.Instance.ModifyDrawDicesAmountModifier(2);
					concentrationEffectSoulHeat10Trigger = false;
				}
				else
				{
					soulHeat10OmenLogic.ActivateOmen(soulHeat10BattleAction, soulHeat10Value, null, null);
				}
			}
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.GoddessCartoucheOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		string omenRawLocalizedDescription = GetOmenRawLocalizedDescription();
		string arg = soulHeat10BattleAction.GetActionDescription(soulHeat10Value).LowercaseFirst();
		string arg2 = soulHeat10BattleAction.GetActionDescription(soulHeat5SecondActionValue).LowercaseFirst().RemoveLastIfDotOrComma();
		return Smart.Format(omenRawLocalizedDescription, soulHeat10Counter, arg) + "\n" + Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("BoneKhopesh_DAnd"), soulHeat5Counter, arg2, soulHeat5BattleAction.GetActionDescription(soulHeat5Value).LowercaseFirst()) + "\n" + base.localizationManager.GetLocalizedCorruptionNotIncreasedByCorruptionModifier();
	}
}
